<template>
  <section class="notes-page">
    <UiPageHeader title="Заметки" eyebrow="Личное пространство" description="Быстрые записи, списки и мысли — отдельно от базы знаний."><template #actions><div class="ui-page-header-stat"><strong>{{ notes.length }}</strong><small>{{ noteWord }}</small></div><UiButton @click="openCreate">Новая заметка</UiButton></template></UiPageHeader>
    <div class="notes-sections panel"><button v-for="section in sections" :key="section.value" type="button" :class="{active:activeSection===section.value}" @click="activeSection=section.value"><span>{{ section.label }}</span><b>{{ section.count }}</b></button></div>
    <div class="notes-workspace panel">
      <aside class="notes-list-pane">
        <div class="notes-search"><UiIcon name="search"/><input ref="searchInput" v-model="search" type="search" placeholder="Поиск по заметкам и меткам"><button v-if="search" type="button" @click="search=''" aria-label="Очистить"><UiIcon name="close"/></button></div>
        <div class="notes-list-meta"><span>{{ filteredNotes.length }} {{ filteredNoteWord }}</span><small v-if="search">по запросу «{{ search }}»</small></div>
        <div v-if="filteredNotes.length" class="notes-list"><button v-for="note in filteredNotes" :key="note.id" type="button" :class="['note-card',{active:activeNote?.id===note.id}]" @click="activeNoteId=note.id"><header><span>{{ note.section }}</span><UiIcon v-if="note.pinned" name="pin"/></header><strong>{{ note.title }}</strong><p>{{ excerpt(note.content) }}</p><footer><span>{{ formatDate(note.updatedAt) }}</span><b v-for="tag in note.tags.slice(0,2)" :key="tag">#{{ tag }}</b></footer></button></div>
        <div v-else class="notes-empty"><UiIcon name="notes"/><strong>{{ notes.length?'Ничего не найдено':'Заметок пока нет' }}</strong><p>{{ notes.length?'Попробуй изменить запрос или раздел.':'Создай первую быструю заметку.' }}</p><UiButton v-if="!notes.length" size="sm" icon="plus" @click="openCreate">Создать</UiButton></div>
      </aside>
      <article v-if="activeNote" class="note-reader"><header><div><span>{{ activeNote.section }}</span><h2>{{ activeNote.title }}</h2><p>Обновлено {{ formatLongDate(activeNote.updatedAt) }}</p></div><div class="note-actions"><UiIconButton icon="pin" :label="activeNote.pinned?'Открепить':'Закрепить'" :variant="activeNote.pinned?'accent':'neutral'" @click="togglePinned"/><UiIconButton icon="edit" label="Редактировать" @click="openEdit(activeNote)"/><UiIconButton icon="trash" label="Удалить" variant="danger" @click="requestDelete(activeNote)"/></div></header><div v-if="activeNote.tags.length" class="note-tags"><button v-for="tag in activeNote.tags" :key="tag" type="button" @click="search=tag">#{{ tag }}</button></div><div class="note-content">{{ activeNote.content }}</div></article>
      <div v-else class="reader-empty"><span><UiIcon name="notes"/></span><strong>Выбери заметку</strong><p>Она откроется здесь для чтения.</p></div>
    </div>
    <NoteEditorModal v-model="isEditorOpen" :note="editingNote" :initial-section="activeSection==='all'?'':activeSection" @save="saveNote"/><UiConfirmModal v-model="isDeleteOpen" title="Удалить заметку?" :message="`Заметка «${deletingNote?.title||''}» будет удалена без возможности восстановления.`" confirm-label="Удалить заметку" @confirm="confirmDelete"/>
  </section>
</template>
<script setup>
import {computed,nextTick,ref,watch} from 'vue';import NoteEditorModal from '../../components/notes/NoteEditorModal.vue';import UiButton from '../../components/ui/UiButton.vue';import UiConfirmModal from '../../components/ui/UiConfirmModal.vue';import UiIcon from '../../components/ui/UiIcon.vue';import UiIconButton from '../../components/ui/UiIconButton.vue';import UiPageHeader from '../../components/ui/UiPageHeader.vue';import {noteStore} from '../../stores/note.store.js';import {useNotification} from '../../composables/ui/useNotification.js';import {pluralizeRu} from '../../utils/formatters/pluralizeRu.js'
const{notify}=useNotification();const notes=noteStore.notes;const search=ref('');const activeSection=ref('all');const activeNoteId=ref('');const searchInput=ref(null);const isEditorOpen=ref(false);const editingNote=ref(null);const isDeleteOpen=ref(false);const deletingNote=ref(null)
const sections=computed(()=>{const counts=new Map();notes.value.forEach(n=>counts.set(n.section,(counts.get(n.section)||0)+1));return[{value:'all',label:'Все заметки',count:notes.value.length},...[...counts.entries()].sort(([a],[b])=>a.localeCompare(b,'ru')).map(([value,count])=>({value,label:value,count}))]});const filteredNotes=computed(()=>{const q=search.value.trim().toLocaleLowerCase('ru');return notes.value.filter(n=>(activeSection.value==='all'||n.section===activeSection.value)&&(!q||[n.title,n.content,n.section,...(n.tags||[])].join(' ').toLocaleLowerCase('ru').includes(q)))});const activeNote=computed(()=>filteredNotes.value.find(n=>n.id===activeNoteId.value)||filteredNotes.value[0]||null);const noteWord=computed(()=>pluralizeRu(notes.value.length,['заметка','заметки','заметок']));const filteredNoteWord=computed(()=>pluralizeRu(filteredNotes.value.length,['заметка','заметки','заметок']))
watch(filteredNotes,items=>{if(!items.some(n=>n.id===activeNoteId.value))activeNoteId.value=items[0]?.id||''},{immediate:true});function openCreate(){editingNote.value=null;isEditorOpen.value=true}function openEdit(note){editingNote.value=note;isEditorOpen.value=true}function saveNote(data){const result=data.id?noteStore.updateNote(data.id,data):noteStore.addNote(data);if(!result.ok){notify(result.message,'warning');return}activeNoteId.value=result.note.id;isEditorOpen.value=false;notify(data.id?'Заметка обновлена':'Заметка создана','success')}function togglePinned(){const result=noteStore.togglePinned(activeNote.value.id);notify(result.ok?(result.note.pinned?'Заметка закреплена':'Заметка откреплена'):result.message,result.ok?'info':'warning')}function requestDelete(note){deletingNote.value=note;isDeleteOpen.value=true}async function confirmDelete(){const note=deletingNote.value;isDeleteOpen.value=false;if(!note)return;const result=await noteStore.deleteNote(note.id);deletingNote.value=null;notify(result.ok?'Заметка удалена':result.message,result.ok?'info':'danger')}function excerpt(v){return String(v||'').replace(/\s+/g,' ').slice(0,120)}function formatDate(v){return new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'short'}).format(new Date(v))}function formatLongDate(v){return new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(v))}async function focusSearch(){await nextTick();searchInput.value?.focus()}defineExpose({focusSearch})
</script>
<style scoped>
.notes-page{display:grid;gap:12px;padding:14px}.notes-sections{display:flex;gap:6px;padding:9px;overflow-x:auto}.notes-sections button{display:flex;align-items:center;gap:7px;min-height:31px;border:1px solid var(--border-color);border-radius:var(--radius-pill);padding:0 10px;color:var(--text-secondary);background:var(--control-bg);white-space:nowrap}.notes-sections button b{min-width:18px;border-radius:99px;padding:2px 5px;color:var(--text-muted);background:var(--card-soft);font-size:9px}.notes-sections button.active{border-color:var(--accent-border);color:var(--text-inverse);background:var(--accent)}.notes-sections button.active b{color:var(--accent);background:var(--text-inverse)}.notes-workspace{min-height:620px;display:grid;grid-template-columns:minmax(280px,350px) minmax(0,1fr);overflow:hidden}.notes-list-pane{min-width:0;display:grid;grid-template-rows:auto auto 1fr;border-right:1px solid var(--border-color);background:var(--card-soft)}.notes-search{display:grid;grid-template-columns:18px 1fr 24px;align-items:center;gap:5px;margin:11px;border:1px solid var(--border-color);border-radius:var(--radius-md);padding:0 8px;color:var(--text-muted);background:var(--field-bg)}.notes-search input{width:100%;min-height:38px;border:0;outline:0;color:var(--text-primary);background:transparent}.notes-search button{border:0;color:var(--text-muted);background:transparent}.notes-list-meta{display:flex;justify-content:space-between;padding:0 12px 9px;color:var(--text-muted);font-size:10px}.notes-list{display:grid;align-content:start;gap:5px;padding:0 7px 8px;overflow-y:auto}.note-card{width:100%;display:grid;gap:5px;border:1px solid transparent;border-radius:var(--radius-md);padding:11px;color:inherit;background:transparent;text-align:left}.note-card:hover{border-color:var(--border-color);background:var(--control-bg)}.note-card.active{border-color:var(--accent-border);background:var(--accent-soft)}.note-card header{display:flex;justify-content:space-between;color:var(--accent);font-size:9px;font-weight:800;text-transform:uppercase}.note-card>strong{font-size:13px}.note-card>p{min-height:32px;margin:0;color:var(--text-secondary);font-size:10px;line-height:1.5}.note-card footer{display:flex;gap:4px;color:var(--text-muted);font-size:9px}.note-card footer span{margin-right:auto}.note-card footer b{border-radius:99px;padding:2px 5px;background:var(--control-bg)}.notes-empty,.reader-empty{display:grid;place-items:center;align-content:center;gap:6px;padding:30px;color:var(--text-muted);text-align:center}.notes-empty p,.reader-empty p{margin:0}.note-reader{min-width:0;padding:clamp(20px,4vw,54px);background:var(--card-solid)}.note-reader>header{display:flex;align-items:start;justify-content:space-between;gap:16px;border-bottom:1px solid var(--border-color);padding-bottom:18px}.note-reader header>div>span{color:var(--accent);font-size:10px;font-weight:800;text-transform:uppercase}.note-reader h2{margin:7px 0 5px;font-size:clamp(24px,3vw,36px)}.note-reader header p{margin:0;color:var(--text-muted);font-size:10px}.note-actions{display:flex;gap:5px}.note-tags{display:flex;flex-wrap:wrap;gap:5px;margin-top:16px}.note-tags button{border:0;border-radius:99px;padding:5px 8px;color:var(--accent);background:var(--accent-soft);font-size:10px}.note-content{max-width:820px;padding:26px 0 60px;font-size:15px;line-height:1.85;white-space:pre-wrap;overflow-wrap:anywhere}.reader-empty{background:var(--card-solid)}.reader-empty>span{width:54px;height:54px;display:grid;place-items:center;border-radius:16px;color:var(--accent);background:var(--accent-soft);font-size:24px}@media(max-width:780px){.notes-page{padding:10px}.notes-workspace{grid-template-columns:1fr}.notes-list-pane{max-height:390px;border-right:0;border-bottom:1px solid var(--border-color)}.note-reader{padding:20px 16px}.note-reader>header{flex-direction:column}.note-actions{align-self:flex-end}}
</style>
